/*
  AEAN Studios animated logo (construction version)
  Usage:
    <script src="/js/aean-logo.js" defer></script>
    <aean-logo></aean-logo>
  Styling (set on the element or a parent):
    color: #fff;                 logo colour (default white)
    --aean-guide: #A18B64;       construction line colour (default Muted Brass)
    width: min(80vw, 760px);     size it like any block element; height follows automatically
  Attributes:
    no-tagline                   hides "Brand identity & creative direction" and trims the space it used
    manual                       stays hidden until .play() is called (used on the home page to wait for the loader)
  JS:
    document.querySelector('aean-logo').play()   replays the animation
*/
(() => {
const P = {"lion": {"src": "data:image/png;base64,", "x": 335, "y": 379, "w": 245, "h": 96}, "letters": [{"src": "data:image/png;base64,", "x": 80, "y": 501, "w": 52, "h": 51}, {"src": "data:image/png;base64,", "x": 157, "y": 501, "w": 42, "h": 51}, {"src": "data:image/png;base64,", "x": 226, "y": 501, "w": 52, "h": 51}, {"src": "data:image/png;base64,", "x": 302, "y": 501, "w": 47, "h": 51}, {"src": "data:image/png;base64,", "x": 423, "y": 501, "w": 36, "h": 51}, {"src": "data:image/png;base64,", "x": 490, "y": 501, "w": 42, "h": 51}, {"src": "data:image/png;base64,", "x": 559, "y": 501, "w": 50, "h": 51}, {"src": "data:image/png;base64,", "x": 635, "y": 501, "w": 49, "h": 51}, {"src": "data:image/png;base64,", "x": 714, "y": 501, "w": 24, "h": 51}, {"src": "data:image/png;base64,", "x": 768, "y": 501, "w": 48, "h": 51}, {"src": "data:image/png;base64,", "x": 849, "y": 501, "w": 35, "h": 51}], "tag": {"src": "data:image/png;base64,", "x": 232, "y": 587, "w": 500, "h": 15}};
const VB_FULL = {x:20, y:300, w:960, h:380}, VB_SHORT = {x:20, y:300, w:960, h:290};
const OUT = 'cubic-bezier(.22,.61,.36,1)', INOUT = 'cubic-bezier(.65,0,.35,1)';
const NS = 'http://www.w3.org/2000/svg';
const CSS = `
:host{display:block;position:relative;width:100%;color:#fff;contain:layout paint}
.part{position:absolute}
.ink{position:absolute;inset:0;background:currentColor;
  -webkit-mask-size:100% 100%;mask-size:100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat}
.lionwrap{-webkit-mask-image:linear-gradient(90deg,#000 40%,transparent 60%);mask-image:linear-gradient(90deg,#000 40%,transparent 60%);
  -webkit-mask-size:250% 100%;mask-size:250% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;
  -webkit-mask-position:0% 0;mask-position:0% 0}
svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;opacity:0;overflow:visible}
svg *{fill:none;stroke:var(--aean-guide,#A18B64);stroke-width:.55}
svg .faint{stroke-opacity:.5}
:host([no-tagline]) .tag{display:none}`;

class AeanLogo extends HTMLElement {
  connectedCallback(){
    if (this._built) return; this._built = true;
    if (!this.hasAttribute('role')) this.setAttribute('role','img');
    if (!this.hasAttribute('aria-label')) this.setAttribute('aria-label','AEAN Studios');
    const short = this.hasAttribute('no-tagline');
    const VB = short ? VB_SHORT : VB_FULL;
    this.style.aspectRatio = `${VB.w} / ${VB.h}`;
    const root = this.attachShadow({mode:'open'});
    const style = document.createElement('style'); style.textContent = CSS; root.appendChild(style);
    const pct = (v,o,s) => ((v-o)/s*100)+'%';
    const place = (el,p) => { el.style.left=pct(p.x,VB.x,VB.w); el.style.top=pct(p.y,VB.y,VB.h);
      el.style.width=(p.w/VB.w*100)+'%'; el.style.height=(p.h/VB.h*100)+'%'; };
    const part = (p, cls) => { const d=document.createElement('div'); d.className='part'+(cls?' '+cls:''); place(d,p);
      const i=document.createElement('div'); i.className='ink'; i.style.webkitMaskImage=i.style.maskImage='url('+p.src+')';
      d.appendChild(i); root.appendChild(d); return d; };

    const svg = document.createElementNS(NS,'svg');
    svg.setAttribute('viewBox',`${VB.x} ${VB.y} ${VB.w} ${VB.h}`); svg.setAttribute('preserveAspectRatio','none');
    svg.setAttribute('aria-hidden','true');
    const guides = [];
    const line = (x1,y1,x2,y2,faint) => { const l=document.createElementNS(NS,'line');
      Object.entries({x1,y1,x2,y2}).forEach(([k,v])=>l.setAttribute(k,v));
      l.setAttribute('pathLength','1'); l.style.strokeDasharray='1'; l.style.strokeDashoffset='1';
      if (faint) l.setAttribute('class','faint'); svg.appendChild(l); guides.push(l); };
    (short ? [379,474,501,551] : [379,474,501,551,588,601]).forEach(y => line(40,y,960,y, y===379||y===474));
    line(482.5,320,482.5,short ? 580 : 660);
    P.letters.forEach(l => { line(l.x+1,492,l.x+1,560,true); line(l.x+l.w-2,492,l.x+l.w-2,560,true); });
    line(335,379,335,474,true); line(580,379,580,474,true);
    root.appendChild(svg);

    this._lion = part(P.lion,'lionwrap');
    this._letters = P.letters.map(p => part(p));
    this._tag = short ? document.createElement('div') : part(P.tag,'tag');
    this._svg = svg; this._guides = guides; this._anims = [];

    const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (this.hasAttribute('manual') && !reduce) { this._hide(); }
    else if ('IntersectionObserver' in window && !reduce) {
      this._hide();
      const io = new IntersectionObserver(es => { if (es.some(e=>e.isIntersecting)) { io.disconnect(); this.play(); } }, {threshold:.3});
      io.observe(this);
    } else this.play();
  }
  _hide(){ [...this._letters, this._tag, this._lion].forEach(el => el.style.opacity = 0); }
  play(){
    if (!this._built) return;
    this._anims.forEach(a => a.cancel()); this._anims = [];
    [...this._letters, this._tag, this._lion].forEach(el => el.style.opacity = '');
    const A = (el,kf,o) => { const a = el.animate(kf, Object.assign({fill:'both'},o)); this._anims.push(a); return a; };
    A(this._svg,[{opacity:1},{opacity:1}],{duration:10});
    this._guides.forEach((g,i) => A(g,[{strokeDashoffset:1},{strokeDashoffset:0}],{duration:700,delay:i<7?i*90:600+(i-7)*25,easing:INOUT}));
    this._letters.forEach((el,i) => A(el,[{opacity:0,transform:'translateY(-35%)'},{opacity:1,transform:'none'}],{duration:650,delay:1200+i*55,easing:OUT}));
    A(this._lion,[{maskPosition:'100% 0',webkitMaskPosition:'100% 0'},{maskPosition:'0% 0',webkitMaskPosition:'0% 0'}],{duration:1500,delay:1500,easing:INOUT});
    A(this._tag,[{opacity:0},{opacity:1}],{duration:800,delay:2700,easing:OUT});
    A(this._svg,[{opacity:1},{opacity:0}],{duration:1000,delay:3500,easing:'ease-in'});
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) this._anims.forEach(a => a.finish());
  }
}
if (!customElements.get('aean-logo')) customElements.define('aean-logo', AeanLogo);
})();
